package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;import java.util.regex.*;
public class UiStructureCheckpointWiringTest {
 private String s(String n)throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",n+".java"));}
 @Test public void uiCheckpointCannotMintImageSlot(){assertThrows(SecurityException.class,()->ReadOnlyCheckpoint.CURRENT.store(Path.of("fixture"),1));assertNotNull(ReadOnlyCheckpoint.PROGRESS_LAYOUT_V41.store(Path.of("fixture"),1));assertNotNull(ReadOnlyCheckpoint.PROGRESS_STRUCTURE_V43.store(Path.of("fixture"),1));}
 @Test public void fixedUiModePreservesOldDescriptors(){assertSame(ReadOnlyCheckpoint.UI_BOUND_POINTS_V53,ReadOnlyCheckpoint.CURRENT);assertEquals(1794466200000L,ReadOnlyCheckpoint.PROGRESS_LAYOUT_V41.starts());assertEquals(1794468900000L,ReadOnlyCheckpoint.PROGRESS_STRUCTURE_V43.starts());assertEquals(1794474000000L,ReadOnlyCheckpoint.PROGRESS_STRUCTURE_V43.expires());assertTrue(ReadOnlyCheckpoint.blocksLiveInput());assertEquals(ReadOnlyCheckpoint.Projection.UI_READY,ReadOnlyCheckpoint.CURRENT.projection());}
 @Test public void uiReadBurnIsIndependentAndZeroImages()throws Exception{String c=s("ReadOnlyCheckpoint");assertTrue(c.contains("UI_READ_1.burned"));assertTrue(c.contains("maxUiReads=1 maxFrames=0 maxOcr=0 maxInput=0"));assertTrue(c.contains("StandardOpenOption.CREATE_NEW"));assertFalse(c.contains("TRUNCATE_EXISTING"));assertTrue(c.contains("switch(CURRENT)"));assertFalse(c.contains("default"));}
 @Test public void uiBranchReturnsBeforeAnyImageGrant()throws Exception{String r=s("CaptureSessionRuntime");int a=r.indexOf("returnReadIntent.anchorCurrent(read.source(),now)"),u=r.indexOf("if(returnReadIntent.uiStructure()){readUiStructureOnOwner();return;}",a),g=r.indexOf("grant=RealCaptureClaim.visible",a);assertTrue(u>a&&g>u);assertTrue(s("VisibleCaptureAuthority").contains("if(i==null||i.uiStructure()||i.checkpoint()!=ReadOnlyCheckpoint.CURRENT"));assertTrue(r.contains("if(returnReadIntent!=null&&returnReadIntent.uiStructure()){closeUiStructureOnOwner();return;}"));}
 @Test public void noCaptureOrInputInUiReaderLifecycle()throws Exception{String r=s("CaptureSessionRuntime");String ui=r.substring(r.indexOf("private AndroidUiStructureReader.Result uiRead"),r.indexOf("private boolean scanContinuable"));for(String bad:new String[]{"RealCaptureClaim.visible","MaaImageBufferAudit","ReviewShizukuPngBinding","SwipeActor","TapActor","BackActor","prepare("})assertFalse(bad,ui.contains(bad));assertTrue(ui.contains("imageAudit=NOT_REQUESTED"));assertTrue(ui.contains("activity.returnReadFrameFinished(this,null,details)"));}
 @Test public void sourceBurnAndPostcheckGuardPublication()throws Exception{String r=s("CaptureSessionRuntime");assertTrue(r.contains("if(!freshUiSource())return false;"));assertTrue(r.contains("checkpoint().burnUiRead("));assertTrue(r.contains("uiSourceAfter=freshUiSource()"));assertTrue(r.contains("returnReadIntent.sourceMatches(r.source().ready())"));assertTrue(r.contains("uiSourceProof.fresh(now)"));assertTrue(r.contains("returnMetadata.currentPublicationAuthorityMatches"));assertTrue(r.contains("token.publish(SystemClock.elapsedRealtime(),current,hidden,source)"));}
 @Test public void allOldRuntimeStartsAndIssuersUseExhaustiveBlocker()throws Exception{
  int count=0;Matcher m=Pattern.compile("(?m)^    static CaptureSessionRuntime (start\\w*)\\([^{}]*\\)\\s*\\{([^{}]*)").matcher(s("CaptureSessionRuntime"));
  while(m.find()){if(m.group(1).equals("startCheckpointRead"))continue;assertTrue(m.group(1),m.group(2).contains("if(ReadOnlyCheckpoint.blocksLiveInput())throw"));count++;}assertTrue(count>=17);
  count=0;int alignment=0,overviewIntent=0,overviewFrame=0;m=Pattern.compile("static [\\w.<>]+ (issue\\w*)\\([^{}]*\\)\\s*\\{([^{}]*)").matcher(s("VisibleCaptureAuthority"));
  while(m.find()){
   if(m.group(1).equals("issueAlignment")){alignment++;continue;} // Independently checked by UiImageAlignmentEntryTest.
   if(m.group(1).equals("issueOverviewIntent")){overviewIntent++;continue;} // Independently checked by OverviewEntryWiringTest.
   if(m.group(1).equals("issueOverviewFrame")){overviewFrame++;continue;}
   if(m.group(1).equals("issueCheckpointIntent")||m.group(1).equals("issueCheckpointFrame"))continue;
   assertTrue(m.group(1),m.group(2).contains("if(ReadOnlyCheckpoint.blocksLiveInput())throw"));count++;
  }
  assertTrue(count>=23);assertEquals(1,alignment);assertEquals(1,overviewIntent);assertEquals(1,overviewFrame);
 }
 @Test public void allFiveInputFactoriesBlocked()throws Exception{int count=0;for(String n:new String[]{"ReviewShizukuSwipeActor","ReviewShizukuTapActor","ReviewShizukuBackActor"}){Matcher m=Pattern.compile("static "+n+" (for\\w*)\\(Context context\\) \\{([^{}]*)").matcher(s(n));while(m.find()){assertTrue(m.group(1),m.group(2).stripLeading().startsWith("if(ReadOnlyCheckpoint.blocksLiveInput())throw"));count++;}}assertEquals(5,count);}
 @Test public void uiDisclosureAndChoiceAreExplicit()throws Exception{String c=s("DormantCaptureConfirmationActivity");assertTrue(c.contains("case UI_STRUCTURE->RootCaptureUi.uiStructureChoice"));assertTrue(s("RootCaptureUi").contains("批准V45设备内UI结构只读：零输入"));assertTrue(s("NativeUiStructureHelper").contains("FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES"));}
 @Test public void uiChoiceBodyAndButtonMatchV45Window()throws Exception{String all=s("RootCaptureUi");int a=all.indexOf("static void uiStructureChoice(");int b=all.indexOf("static void structureReadChoice(",a);String body=all.substring(a,b);assertTrue(body.contains("设备内UI结构只读 v45"));assertTrue(body.contains("本次独立授权窗口2026-11-12 09:00–10:00 UTC，09:57 UTC停止接纳"));assertTrue(body.contains("批准V45设备内UI结构只读：零输入"));assertFalse(body.contains("v44"));assertFalse(body.contains("授权至2026-11-12 09:00 UTC"));}
 @Test public void fixedVmClasspathPreservesAndroidEnvironment()throws Exception{String reader=s("AndroidUiStructureReader");assertTrue(reader.contains("String[] command = {\"/system/bin/app_process\", \"-cp\", apk, \"/system/bin\", HELPER, nonce, Long.toString(deadline)};"));assertTrue(reader.contains("service.newProcess(command, null, null)"));assertFalse(reader.contains("CLASSPATH="));assertFalse(reader.contains("/system/bin/env"));assertFalse(reader.contains("/system/bin/sh"));int validated=reader.indexOf("String apk =");assertTrue(validated>=0&&validated<reader.indexOf("String[] command"));}
}
